#!/bin/bash
set -eo pipefail
export PYTHONDONTWRITEBYTECODE=1
export SMALLFIT_CONTINUATION_
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B -c 'import base64,hashlib,json,os
from pathlib import Path
config=json.loads(base64.b64decode(os.environ['"'"'SMALLFIT_CONTINUATION_CONFIG'"'"'],validate=True))
folder=Path(config['"'"'remote_root'"'"'])/'"'"'records/deployment_code_v04'"'"'
folder.mkdir(parents=True,exist_ok=True)
for row in json.loads(base64.b64decode('"'"''"'"',validate=True)):
    if row['"'"'name'"'"'] not in ('"'"'deploy_precip_smallfit_continuation_v03.py'"'"','"'"'deploy_precip_smallfit_reuse_v04.py'"'"'):
        raise PermissionError('"'"'Unexpected deployment source name'"'"')
    data=base64.b64decode(row['"'"'base64'"'"'],validate=True)
    if hashlib.sha256(data).hexdigest()!=row['"'"'sha256'"'"']:
        raise PermissionError('"'"'Deployment source digest differs'"'"')
    path=folder/row['"'"'name'"'"']
    if path.is_symlink():
        raise PermissionError('"'"'Linked deployment source'"'"')
    if path.exists():
        if path.read_bytes()!=data:
            raise PermissionError('"'"'Existing deployment source differs'"'"')
    else:
        with path.open('"'"'xb'"'"') as stream: stream.write(data)
entry=folder/'"'"'deploy_precip_smallfit_reuse_v04.py'"'"'
exec(compile(entry.read_bytes(),str(entry),'"'"'exec'"'"'),{'"'"'__name__'"'"':'"'"'__main__'"'"','"'"'__file__'"'"':str(entry)})
'
